H.background();
const r1 = P.r1, r2 = P.r2, a = P.a, probe = P.probe;
const f = x => a * (x - r1) * (x - r2);
const v = H.plot2d({ xMin: -7, xMax: 7, yMin: -10, yMax: 10 });
v.grid(); v.axes();
v.fn(f, { color: H.colors.accent, width: 3 });
v.dot(r1, 0, { r: 6, fill: H.colors.good });
v.dot(r2, 0, { r: 6, fill: H.colors.good });
const fp = f(probe);
const onAxis = Math.abs(fp) < 1e-6;
v.line(probe, 0, probe, fp, { color: onAxis ? H.colors.good : H.colors.warn, width: 2, dash: [4, 4] });
v.dot(probe, fp, { r: 7, fill: onAxis ? H.colors.good : H.colors.warn });
